#include <iostream>
#include <stdexcept>
using namespace std;

const int MAX = 5;

class Stack {
    int arr[MAX];
    int top;
public:
    Stack() { top = -1; }

    bool isEmpty() { return top == -1; }
    bool isFull()  { return top == MAX - 1; }
    int  size()    { return top + 1; }

    void push(int x) {
        if (isFull()) throw overflow_error("Stack Overflow");
        arr[++top] = x;          // first move top up, then store
    }

    int pop() {
        if (isEmpty()) throw underflow_error("Stack Underflow");
        return arr[top--];       // first read, then move top down
    }

    int peek() {
        if (isEmpty()) throw underflow_error("Stack is empty");
        return arr[top];
    }

    void display() {
        if (isEmpty()) { cout << "Stack is empty" << endl; return; }
        cout << "Top -> ";
        for (int i = top; i >= 0; i--) cout << arr[i] << " ";
        cout << endl;
    }
};

int main() {
    Stack s;
    try {
        s.push(10); s.push(20); s.push(30);
        s.display();                               // Top -> 30 20 10
        cout << "Popped: " << s.pop() << endl;     // 30
        cout << "Top now: " << s.peek() << endl;   // 20
        s.pop(); s.pop();
        s.pop();                                   // underflow!
    }
    catch (const exception& e) {
        cout << "Error: " << e.what() << endl;
    }
    return 0;
}

struct Node {
    int data;
    Node* next;
};

class LinkedStack {
    Node* topPtr = nullptr;
public:
    bool isEmpty() { return topPtr == nullptr; }

    void push(int x) {
        Node* n = new Node{x, topPtr};   // new node points to old top
        topPtr = n;                      // new node becomes the top
    }

    int pop() {
        if (isEmpty()) throw underflow_error("Stack Underflow");
        Node* t = topPtr;
        int value = t->data;
        topPtr = topPtr->next;           // move top down
        delete t;                        // free memory
        return value;
    }

    int peek() {
        if (isEmpty()) throw underflow_error("Stack is empty");
        return topPtr->data;
    }

    ~LinkedStack() { while (!isEmpty()) pop(); }   // RAII cleanup
};

