string reverseText(const string& s) {
    stack<char> st;
    for (char c : s) st.push(c);
    string result;
    while (!st.empty()) {
        result += st.top();
        st.pop();
    }
    return result;
}
// reverseText("PATNA") returns "ANTAP"

bool isBalanced(const string& exp) {
    stack<char> st;
    for (char c : exp) {
        if (c == '(' || c == '[' || c == '{') {
            st.push(c);
        } else if (c == ')' || c == ']' || c == '}') {
            if (st.empty()) return false;
            char open = st.top(); st.pop();
            if ((c == ')' && open != '(') ||
                (c == ']' && open != '[') ||
                (c == '}' && open != '{'))
                return false;
        }
    }
    return st.empty();
}

int prec(char op) {
    if (op == '^') return 3;
    if (op == '*' || op == '/' || op == '%') return 2;
    if (op == '+' || op == '-') return 1;
    return 0;                         // for '('
}

string infixToPostfix(const string& infix) {
    stack<char> st;
    string out;
    for (char c : infix) {
        if (c == ' ') continue;
        if (isalnum(c)) out += c;                       // operand
        else if (c == '(') st.push(c);
        else if (c == ')') {
            while (!st.empty() && st.top() != '(') { out += st.top();
st.pop(); }
            if (!st.empty()) st.pop();                  // remove '('
        }
        else {                                          // operator
            while (!st.empty() && st.top() != '(' &&
                   (prec(st.top()) > prec(c) ||
                   (prec(st.top()) == prec(c) && c != '^'))) {
                out += st.top(); st.pop();
            }
            st.push(c);
        }
    }
    while (!st.empty()) { out += st.top(); st.pop(); }
    return out;
}
// infixToPostfix("(A+B)*C-D/E") returns "AB+C*DE/-"

#include <iostream>
#include <stack>
#include <sstream>
#include <string>
#include <stdexcept>
using namespace std;

double evaluatePostfix(const string& exp) {      // tokens separated by spaces
    stack<double> st;
    stringstream ss(exp);
    string tok;
    while (ss >> tok) {
        if (tok == "+" || tok == "-" || tok == "*" || tok == "/") {
            if (st.size() < 2) throw runtime_error("Invalid expression");
            double b = st.top(); st.pop();      // right operand
            double a = st.top(); st.pop();      // left operand
            if      (tok == "+") st.push(a + b);
            else if (tok == "-") st.push(a - b);
            else if (tok == "*") st.push(a * b);
            else {
                if (b == 0) throw runtime_error("Division by zero");
                st.push(a / b);
            }
        } else {
            st.push(stod(tok));                 // number (may throw invalid_argument)
        }
    }
    if (st.size() != 1) throw runtime_error("Invalid expression");
    return st.top();
}

int main() {
    try {
        cout << evaluatePostfix("6 2 3 + * 4 -") << endl;    // 26
        cout << evaluatePostfix("10 2 8 * + 3 -") << endl;   // 23
    }
    catch (const exception& e) { cout << "Error: " << e.what() << endl; }
    return 0;
}

#include <iostream>
#include <stack>
using namespace std;

int main() {
    int n;
    cout << "Enter a decimal number: ";
    cin >> n;
    if (n == 0) { cout << "Binary: 0" << endl; return 0; }
    stack<int> st;
    int temp = n;
    while (temp > 0) {
        st.push(temp % 2);
        temp /= 2;
    }
    cout << "Binary of " << n << ": ";
    while (!st.empty()) { cout << st.top(); st.pop(); }
    cout << endl;
    return 0;
}

bool isPalindrome(const string& w) {
    stack<char> st;
    for (char c : w) st.push(toupper(c));
    for (char c : w) {
        if (st.top() != toupper(c)) return false;
        st.pop();
    }
    return true;
}
// isPalindrome("Madam") -> true,  isPalindrome("Patna") -> false

