#include <iostream>
#include <stack>
#include <string>
using namespace std;

stack<string> undoSt, redoSt;

void doAction(const string& a) {
    undoSt.push(a);
    while (!redoSt.empty()) redoSt.pop();   // a new action clears redo
    cout << "Done: " << a << endl;
}

void undo() {
    if (undoSt.empty()) { cout << "Nothing to undo" << endl; return; }
    cout << "Undo: " << undoSt.top() << endl;
    redoSt.push(undoSt.top()); undoSt.pop();
}

void redo() {
    if (redoSt.empty()) { cout << "Nothing to redo" << endl; return; }
    cout << "Redo: " << redoSt.top() << endl;
    undoSt.push(redoSt.top()); redoSt.pop();
}

int main() {
    doAction("type Hello");
    doAction("make bold");
    doAction("change colour");
    undo();
    undo();
    redo();
    return 0;
}

